CREATE TABLE roles(id UUID PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE users(id UUID PRIMARY KEY,role_id UUID NOT NULL REFERENCES roles(id),email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,enabled BOOLEAN NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE clients(id UUID PRIMARY KEY,user_id UUID NOT NULL UNIQUE REFERENCES users(id),full_name VARCHAR(200) NOT NULL,phone VARCHAR(50));
CREATE TABLE employees(id UUID PRIMARY KEY,user_id UUID NOT NULL UNIQUE REFERENCES users(id),full_name VARCHAR(200) NOT NULL,position VARCHAR(100));
CREATE TABLE outbox_events(event_id UUID PRIMARY KEY,topic VARCHAR(120) NOT NULL,aggregate_id UUID NOT NULL,event_type VARCHAR(100) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published BOOLEAN NOT NULL,published_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL);
